ANALYSIS:
- The rule accesses the `pipeline-required-tasks` data key from the policy data, checking its structure and content
- The rule iterates over entries in `data["pipeline-required-tasks"]` and validates that each entry's `effective_on` field is a valid RFC3339 timestamp format
- The core validation logic triggers a violation when `time.parse_rfc3339_ns(effective_on)` fails, indicating an invalid timestamp format
- The result is generated as a deny rule with failure severity containing the specific error message about the invalid timestamp format

RULE:
```rego
package tasks

import rego.v1
import data.lib
import data.lib.json as j
import data.lib.tekton

_data_errors contains error if {
	some key, entries in data["pipeline-required-tasks"]
	some i, entry in entries
	effective_on := entry.effective_on
	not time.parse_rfc3339_ns(effective_on)
	error := {
		"message": sprintf(
			"pipeline-required-tasks.%s[%d].effective_on is not valid RFC3339 format: %q",
			[key, i, effective_on],
		),
		"severity": "failure",
	}
}

# METADATA
# title: Data provided
# description: >-
#   Confirm the expected data keys have been provided in the expected format. The keys are
#   `pipeline-required-tasks` and `required-tasks`.
# custom:
#   short_name: data_provided
#   failure_msg: '%s'
#   solution: If provided, ensure the data is in the expected format.
#   collections:
#   - redhat
#   - redhat_rpms
#   - policy_data
#
deny contains result if {
	some e in _data_errors
	result := lib.result_helper_with_severity(rego.metadata.chain(), [e.message], e.severity)
}
```

