ANALYSIS:
- The rule accesses PipelineRun attestations and extracts task information using the `tekton.tasks` function, checking against a list of required hermetic tasks defined in rule data.
- It iterates over tasks in the attestations and checks if each task matches a required hermetic task name, then verifies whether the task was executed with the `HERMETIC=true` parameter.
- The core validation logic triggers a violation if a required hermetic task is found but does not have the `HERMETIC` parameter set to `"true"`, using the `_task_is_hermetic` helper function.
- The result is generated as a deny rule that collects all non-compliant tasks and formats them into a structured failure message using `lib.result_helper`.

RULE:
```rego
package hermetic_task

import rego.v1
import data.lib
import data.lib.tekton

_not_hermetic_tasks contains task if {
	required_hermetic_tasks := lib.rule_data("required_hermetic_tasks")
	some attestation in lib.pipelinerun_attestations
	some task in tekton.tasks(attestation)
	some required_hermetic_task in required_hermetic_tasks
	tekton.task_name(task) == required_hermetic_task
	not _task_is_hermetic(task)
}

_task_is_hermetic(task) if {
	tekton.task_param(task, "HERMETIC")
	tekton.task_param(task, "HERMETIC") == "true"
}

# METADATA
# title: Task called with hermetic param set
# description: >-
#   Verify the task in the PipelineRun attestation was invoked with the
#   proper parameters to make the task execution hermetic.
# custom:
#   short_name: hermetic
#   failure_msg: >-
#     Task '%s' was not invoked with the hermetic parameter set
#   solution: >-
#     Make sure the task has the input parameter 'HERMETIC' set to
#     'true'.
#   collections:
#   - redhat
#   depends_on:
#   - attestation_type.known_attestation_type
#
deny contains result if {
	some not_hermetic_task in _not_hermetic_tasks
	result := lib.result_helper(rego.metadata.chain(), [tekton.task_name(not_hermetic_task)])
}
