ANALYSIS:
- The rule accesses Tekton pipeline task references through `tekton.unpinned_task_references` and `lib.tasks_from_pipelinerun`, checking for unpinned task definitions.
- It iterates over unpinned task references in Tekton pipelines, extracting task names and reference information using `_task_info` helper function that formats the task reference with key and pinned_ref.
- The core validation logic triggers a violation when any task reference is found to be unpinned, identified by `tekton.unpinned_task_references` returning non-empty results.
- The result is generated using `lib.result_helper_with_term` which creates a warning message containing the pipeline task name and formatted task reference information for each unpinned task.

RULE:
```rego
package trusted_task

import rego.v1
import data.lib
import data.lib.image
import data.lib.tekton

_task_info(task) := info if {
	ref := tekton.task_ref(task)
	info := sprintf("%s@%s", [object.get(ref, "key", ""), object.get(ref, "pinned_ref", "")])
}

# METADATA
# title: Task references are pinned
# description: >-
#   Check if all Tekton Tasks use a Task definition by a pinned reference. When using the git
#   resolver, a commit ID is expected for the revision parameter. When using the bundles resolver,
#   the bundle parameter is expected to include an image reference with a digest.
# custom:
#   short_name: pinned
#   failure_msg: Pipeline task %q uses an unpinned task reference, %s
#   solution: >-
#     Update the Pipeline definition so that all Task references have a pinned value as mentioned
#     in the description.
#   collections:
#   - redhat
#   - redhat_rpms
#   effective_on: 2024-05-07T00:00:00Z
#
warn contains result if {
	some task in tekton.unpinned_task_references(lib.tasks_from_pipelinerun)
	result := lib.result_helper_with_term(
		rego.metadata.chain(),
		[tekton.pipeline_task_name(task), _task_info(task)],
		tekton.task_name(task),
	)
}
