ANALYSIS:
- The rule accesses **Tekton PipelineRun attestations** to retrieve task execution status information, including task details and their conditions.
- It iterates over **tasks within the PipelineRun** and checks the status of each task, handling both SLSA v0.2 and v1.0 status formats to determine if a task succeeded, failed, or is missing.
- The core validation logic triggers a violation when any task's status is not "Succeeded", including cases where the status is "Failed" or "MISSING".
- The result is generated by calling `lib.result_helper_with_term` to produce a structured failure message identifying the failing task and its status.

RULE:
```rego
package tasks

import rego.v1
import data.lib
import data.lib.json as j
import data.lib.tekton

_slsav1_status(condition) := status if {
	condition.status == "False"
	status := "Failed"
}

_status(task) := status if {
	# Handle SLSA Provenance v0.2
	task.status
	not task.status.conditions
	status := [s |
		s := task.status
	]
} else := status if {
	# Handle SLSA Provenance v1.0
	task.status.conditions
	status := [s |
		some condition in task.status.conditions
		condition.type == "Succeeded"
		s := _slsav1_status(condition)
	]

	# if task.status.conditions = [], we want ["MISSING"] returned
	count(status) > 0
} else := ["MISSING"]

# METADATA
# title: Successful pipeline tasks
# description: >-
#   Ensure that all of the Tasks in the Pipeline completed successfully. Note that
#   skipped Tasks are not taken into account and do not influence the outcome.
# custom:
#   short_name: successful_pipeline_tasks
#   failure_msg: Pipeline task %q did not complete successfully, %q
#   solution: >-
#     Make sure the build pipeline is properly configured so all the tasks can be
#     executed successfully.
#   collections:
#   - minimal
#   - redhat
#   - redhat_rpms
#   - slsa3
#   depends_on:
#   - tasks.pipeline_has_tasks
#
deny contains result if {
	some att in lib.pipelinerun_attestations
	some task in tekton.tasks(att)
	some status in _status(task)
	status != "Succeeded"
	result := lib.result_helper_with_term(
		rego.metadata.chain(),
		[tekton.pipeline_task_name(task), status], tekton.pipeline_task_name(task),
	)
}
```

